'use strict';
const VERSION = '__VERSION__';
const SHELL_CACHE = 'dal-shell-' + VERSION;
const MEDIA_CACHE = 'dal-media';          // kept across versions; stale files are removed by hash
const SHELL = __SHELL__;                  // pages, styles, scripts, pictures: stored on install
const MEDIA = __MEDIA__;                  // narration, PDFs, videos: { path: hash }, stored on demand
const COURSES = __COURSES__;              // { slug: { files: [...], bytes } } for "Save for offline"

const BASE = new URL('./', self.location).href;
const rel = (url) => { const u = new URL(url); return u.href.startsWith(BASE) ? decodeURIComponent(u.pathname.slice(new URL(BASE).pathname.length)) : null; };
const abs = (path) => new URL(path, BASE).href;

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(SHELL_CACHE).then((cache) =>
    // One by one, so a single missing file never blocks the install.
    Promise.all(SHELL.map((p) => cache.add(new Request(abs(p), { cache: 'reload' })).catch(() => {})))
  ));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) {
      if (k.startsWith('dal-shell-') && k !== SHELL_CACHE) await caches.delete(k);
    }
    // Drop media that changed or was removed since it was saved.
    const media = await caches.open(MEDIA_CACHE);
    for (const req of await media.keys()) {
      const res = await media.match(req);
      const p = rel(req.url);
      if (!p || !MEDIA[p] || (res && res.headers.get('x-dal-hash') !== MEDIA[p])) await media.delete(req);
    }
    await self.clients.claim();
  })());
});

async function saveMedia(path) {
  const cache = await caches.open(MEDIA_CACHE);
  const url = abs(path);
  if (await cache.match(url)) return true;
  const res = await fetch(url, { cache: 'reload' });
  if (!res.ok) return false;
  const body = await res.blob();
  const headers = new Headers(res.headers);
  headers.set('x-dal-hash', MEDIA[path] || '');
  headers.set('Content-Length', String(body.size));
  await cache.put(url, new Response(body, { status: 200, headers }));
  return true;
}

function rangeResponse(res, rangeHeader) {
  return res.arrayBuffer().then((buf) => {
    const m = /bytes=(\d*)-(\d*)/.exec(rangeHeader || '') || [];
    let start = m[1] ? +m[1] : 0;
    let end = m[2] ? +m[2] : buf.byteLength - 1;
    if (!m[1] && m[2]) { start = Math.max(0, buf.byteLength - +m[2]); end = buf.byteLength - 1; }
    end = Math.min(end, buf.byteLength - 1);
    return new Response(buf.slice(start, end + 1), {
      status: 206,
      headers: {
        'Content-Type': res.headers.get('Content-Type') || 'application/octet-stream',
        'Content-Range': `bytes ${start}-${end}/${buf.byteLength}`,
        'Content-Length': String(end - start + 1),
        'Accept-Ranges': 'bytes'
      }
    });
  });
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const path = rel(req.url);
  if (path === null) return;

  // Narration, PDFs and videos.
  if (MEDIA[path]) {
    event.respondWith((async () => {
      const hit = await caches.match(abs(path), { cacheName: MEDIA_CACHE });
      if (hit) return req.headers.has('range') ? rangeResponse(hit, req.headers.get('range')) : hit;
      // Not saved yet: play from the network and keep a copy for next time (offline).
      event.waitUntil(saveMedia(path).catch(() => {}));
      return fetch(req);
    })());
    return;
  }

  // Pages and everything else: from the device first, network as a fallback.
  event.respondWith((async () => {
    const key = abs(path === '' ? 'index.html' : path.endsWith('/') ? path + 'index.html' : path);
    const hit = await caches.match(key, { cacheName: SHELL_CACHE, ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (res.ok && path.startsWith('courses/')) {
        const copy = res.clone();
        caches.open(SHELL_CACHE).then((c) => c.put(key, copy));
      }
      return res;
    } catch (e) {
      if (req.mode === 'navigate') {
        const home = await caches.match(abs('index.html'), { cacheName: SHELL_CACHE });
        if (home) return home;
      }
      throw e;
    }
  })());
});

// Messages from assets/js/pwa.js
self.addEventListener('message', (event) => {
  const msg = event.data || {};
  const reply = (data) => event.source && event.source.postMessage(data);
  if (msg === 'skipWaiting' || msg.type === 'skipWaiting') { self.skipWaiting(); return; }

  if (msg.type === 'courseStatus') {
    event.waitUntil((async () => {
      const c = COURSES[msg.course];
      if (!c) return reply({ type: 'courseStatus', course: msg.course, total: 0, saved: 0, bytes: 0 });
      const cache = await caches.open(MEDIA_CACHE);
      let saved = 0;
      for (const p of c.files) if (await cache.match(abs(p))) saved++;
      reply({ type: 'courseStatus', course: msg.course, total: c.files.length, saved, bytes: c.bytes });
    })());
  }

  if (msg.type === 'saveCourse') {
    event.waitUntil((async () => {
      const c = COURSES[msg.course];
      if (!c) return;
      let done = 0, failed = 0;
      const queue = c.files.slice();
      const worker = async () => {
        while (queue.length) {
          const p = queue.shift();
          const ok = await saveMedia(p).catch(() => false);
          ok ? done++ : failed++;
          reply({ type: 'saveProgress', course: msg.course, done, failed, total: c.files.length });
        }
      };
      await Promise.all([worker(), worker(), worker()]);
      reply({ type: 'saveDone', course: msg.course, done, failed, total: c.files.length });
    })());
  }

  if (msg.type === 'removeCourse') {
    event.waitUntil((async () => {
      const c = COURSES[msg.course];
      const cache = await caches.open(MEDIA_CACHE);
      if (c) for (const p of c.files) await cache.delete(abs(p));
      reply({ type: 'courseStatus', course: msg.course, total: c ? c.files.length : 0, saved: 0, bytes: c ? c.bytes : 0 });
    })());
  }
});
